import {restaurants,origins} from './data.js';
import {defaults,normalize,today,parsePrompt,rankRestaurants,links,timeline,calendar,encodePlan,decodePlan} from './planner.js';
const $=s=>document.querySelector(s);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE='sidequest.plans.v1';
let state=parsePrompt($('#prompt').value,defaults()).state;
let selected=null, lastPrompt=$('#prompt').value, toastTimer;
function readSaved(){try{const data=JSON.parse(localStorage.getItem(STORE)||'[]');return Array.isArray(data)?data.filter(x=>x&&typeof x.id==='string'&&restaurants.some(r=>r.id===x.restaurant)).slice(0,20).map(x=>({...x,state:normalize(x.state)})):[];}catch{return[];}}
function writeSaved(data){try{localStorage.setItem(STORE,JSON.stringify(data));updateCount();return true;}catch{notify('Your browser could not save this plan. Try sharing or calendar export.');return false;}}
function updateCount(){$('#saved-count').textContent=readSaved().length;}
function notify(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function modal(title,content){$('#modal-title').textContent=title;$('#modal-content').innerHTML=content;if(!$('#modal').open)$('#modal').showModal();}
function notice(text,warn=false){$('#parse-notice').textContent=text;$('#parse-notice').classList.toggle('warning',warn);}
for(const o of origins)$('#origin').add(new Option(o.name,o.id));
for(let n=1;n<=10;n++)$('#party').add(new Option(`${n} ${n===1?'guest':'guests'}`,n));
$('#date').min=today();
function sync(){
  for(const key of ['date','time','party','budget','origin','cuisine']){const el=$('#'+key);if(key==='budget'&&![...el.options].some(o=>Number(o.value)===state.budget))el.add(new Option('$'+state.budget,state.budget));el.value=state[key];}
  document.querySelectorAll('[data-vibe]').forEach(b=>{b.classList.toggle('active',b.dataset.vibe===state.vibe);b.setAttribute('aria-pressed',String(b.dataset.vibe===state.vibe));});
}
function art(r){
  let inside='';
  if(r.art==='cinema')inside='<rect x="73" y="22" width="154" height="88" rx="3" fill="#faf6ee" stroke="#85769c" stroke-width="2"/><path d="m86 100 36-38 31 22 25-36 38 52" fill="#b6c793"/><circle cx="190" cy="43" r="10" fill="#eebf72"/><path d="M45 25q105 27 210 0" fill="none" stroke="#6c6282"/><g fill="#fff5bf"><circle cx="66" cy="30" r="3"/><circle cx="99" cy="36" r="3"/><circle cx="132" cy="39" r="3"/><circle cx="165" cy="39" r="3"/><circle cx="198" cy="36" r="3"/><circle cx="231" cy="30" r="3"/></g><ellipse cx="150" cy="126" rx="100" ry="9" fill="#a292bf" opacity=".22"/><path d="M94 134v-17m112 17v-17" stroke="#6c6282" stroke-width="3"/><ellipse cx="150" cy="113" rx="67" ry="9" fill="#7b6b90"/><ellipse cx="150" cy="109" rx="67" ry="9" fill="#fffbef"/><path d="M149 108v-17" stroke="#b9a76c" stroke-width="3"/><ellipse cx="149" cy="88" rx="3" ry="6" fill="#edb85c"/>';
  else{inside='<ellipse cx="150" cy="126" rx="85" ry="9" fill="#333" opacity=".09"/><ellipse cx="150" cy="84" rx="81" ry="49" fill="#fcfaf2"/><ellipse cx="150" cy="84" rx="66" ry="38" fill="none" stroke="#d8d2c2" stroke-width="2"/><path d="M48 45v74m-8-74v20q8 10 16 0V45m194 0v74m0-74q-18 25 0 34" stroke="#646850" stroke-width="3" fill="none" stroke-linecap="round"/>';
  if(r.art==='pasta')inside+='<g fill="none" stroke="#deb358" stroke-width="8" stroke-linecap="round"><path d="M111 66q60-10 66 11t-61 11q-10-18 66-9"/><path d="M116 94q58 13 69-10M123 57q58 12 57 27M105 77q57 29 82 11"/></g><g fill="#bf6048"><circle cx="125" cy="71" r="6"/><circle cx="175" cy="89" r="5"/></g><path d="M145 71q-17-28 5-20 16 6-5 20m0 0q27-17 25 0-6 14-25 0" fill="#66834f"/>';
  else if(r.art==='sushi')inside+='<g stroke="#465e4b" stroke-width="7" fill="#f1e9cc"><ellipse cx="125" cy="71" rx="14" ry="11"/><ellipse cx="160" cy="66" rx="14" ry="11"/><ellipse cx="186" cy="82" rx="14" ry="11"/><ellipse cx="149" cy="93" rx="14" ry="11"/><ellipse cx="111" cy="94" rx="14" ry="11"/></g><g fill="#cb885e"><circle cx="125" cy="71" r="4"/><circle cx="160" cy="66" r="4"/><circle cx="186" cy="82" r="4"/><circle cx="149" cy="93" r="4"/><circle cx="111" cy="94" r="4"/></g><path d="m218 22 30 96m-22-99 30 96" stroke="#b6956b" stroke-width="4"/>';
  else inside+='<g fill="#759156"><ellipse cx="121" cy="70" rx="18" ry="12" transform="rotate(-25 121 70)"/><ellipse cx="161" cy="64" rx="18" ry="12"/><ellipse cx="180" cy="89" rx="18" ry="12"/><ellipse cx="130" cy="99" rx="18" ry="12"/></g><g fill="#b86646"><ellipse cx="147" cy="81" rx="23" ry="13" transform="rotate(-25 147 81)"/><circle cx="112" cy="88" r="7"/><circle cx="183" cy="69" r="7"/></g><g fill="#ece1ad"><rect x="124" y="64" width="9" height="9" transform="rotate(20 124 64)"/><rect x="166" y="88" width="9" height="9"/></g><path d="M170 50a14 14 0 0 1 17 12z" fill="#edcf69"/>';
  }
  return `<svg viewBox="0 0 300 150" aria-hidden="true"><circle cx="263" cy="19" r="50" fill="#fff" opacity=".18"/><circle cx="35" cy="137" r="60" fill="#fff" opacity=".13"/>${inside}</svg>`;
}
function mapArt(r){
  const o=origins.find(x=>x.id===state.origin);const point=p=>[25+(p.lng+122.45)/.065*280,130-(p.lat-37.75)/.055*110];const[a,b]=point(o),[c,d]=point(r);
  return `<div class="area-map"><svg viewBox="0 0 340 145" aria-label="Schematic of starting point and restaurant; not a navigation map" role="img"><defs><pattern id="streets" width="23" height="21" patternTransform="rotate(-10)" patternUnits="userSpaceOnUse"><rect width="23" height="21" fill="#e9ebe5"/><path d="M0 0H23M0 0V21" stroke="#fafbf7" stroke-width="6"/></pattern></defs><rect width="340" height="145" fill="url(#streets)"/><path d="m284 0 12 30-13 34 25 33 32 9V0" fill="#d6e3e9"/><path d="M5 130 215 0" stroke="#fafbf7" stroke-width="10"/><rect x="33" y="25" width="35" height="28" rx="6" fill="#cdddbb"/><rect x="157" y="105" width="30" height="20" rx="4" fill="#cdddbb"/><text x="137" y="44" fill="#8c9388" font-size="8" font-family="sans-serif" letter-spacing="1.5">SAN FRANCISCO</text><path d="M${a} ${b} L${c} ${d}" stroke="#8e78b6" stroke-width="2.5" stroke-dasharray="4 4" fill="none"/><circle cx="${a}" cy="${b}" r="7" fill="#292c33" stroke="white" stroke-width="3"/><circle cx="${c}" cy="${d}" r="9" fill="#9fc458" stroke="white" stroke-width="3"/></svg><span class="map-label">Area sketch · check Maps for the actual route</span></div>`;
}
function render(){
  sync(); const ranked=rankRestaurants(state);if(!ranked.some(r=>r.id===selected))selected=ranked[0]?.id||null;
  $('#result-count').textContent=ranked.length;
  $('#cards').innerHTML=ranked.length?ranked.map((r,i)=>`<article class="card ${selected===r.id?'selected':''}"><div class="card-art" style="background:${r.color}">${art(r)}<span class="card-kicker">${selected===r.id?'✓ YOUR PICK':i===0?'A GOOD MATCH':r.walkIn?'EASY & CASUAL':r.tags.includes('vegan')?'PLANT-BASED':'WORTH AN EVENING'}</span><span class="art-caption">SIDEQUEST ILLUSTRATION</span></div><div class="card-body"><div class="card-meta"><span>${r.neighborhood} · ${r.cuisine}</span></div><h3>${r.name}</h3><p class="card-description">${r.description}</p><div class="card-bottom"><div class="price">~$${r.allowance}<span>/ person · food allowance</span></div><button class="choose" data-select="${r.id}" aria-pressed="${selected===r.id}" aria-label="${selected===r.id?'Selected':'Choose'} ${r.name}">${selected===r.id?'✓ In your plan':'Choose this place'}</button></div></div></article>`).join(''):`<div class="empty"><span class="empty-icon">✳</span><h3>Let’s open up the options.</h3><p>No places in our small SF collection match this budget, cuisine, and party size. Try a higher budget or another cuisine.</p><button class="outline" id="empty-reset">Reset filters</button></div>`;
  $('#empty-reset')?.addEventListener('click',reset);
  document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selected=b.dataset.select;render();notify(`${restaurants.find(r=>r.id===selected).name} added to your plan.`);});
  renderItinerary();
}
function validDinner(){return state.time>='17:00'&&state.time<='21:00'&&+timeline(state).dinner>Date.now();}
function renderItinerary(){
  const el=$('#itinerary-content');const r=restaurants.find(r=>r.id===selected);
  if(!r){el.innerHTML='<div class="trip-body empty"><span class="empty-icon">⌖</span><p>Choose a matching restaurant to connect your evening.</p></div>';return;}
  const t=timeline(state),o=origins.find(x=>x.id===state.origin),l=links(state,r);
  const day=new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',weekday:'short',timeZone:'UTC'}).format(new Date(state.date+'T12:00:00Z'));
  const valid=validDinner();
  el.innerHTML=`${mapArt(r)}<div class="trip-body"><div class="trip-date"><span>${day} · ${state.party} ${state.party===1?'guest':'guests'}</span><span class="status">Not booked</span></div>${!valid?'<div class="closed-note">Choose a future dinner date and time between 5–9pm to use this plan.</div>':''}<ol class="timeline"><li><time>${t.leaveLabel}</time><div><strong>Time to head out</strong><p>${o.name} · allow ${state.travel} min</p></div></li><li><time>${t.arriveLabel}</time><div><strong>A little breathing room</strong><p>${state.buffer} min buffer before dinner</p></div></li><li><time>${t.dinnerLabel}</time><div><strong>Dinner at ${r.name}</strong><p>${r.neighborhood} · ${r.walkIn?'Walk-in; seating not guaranteed':'Confirm your table with the restaurant'}</p></div></li></ol><div class="travel-settings"><label>Travel allowance (min)<input id="travel" type="number" value="${state.travel}" min="5" max="180" step="1"></label><label>Arrival buffer (min)<input id="buffer" type="number" value="${state.buffer}" min="0" max="60" step="1"></label></div><p class="trip-note">All times Pacific. Travel is your editable allowance, not a live ETA. Check traffic in Maps before leaving.</p><div class="trip-cost"><span>Food allowance · ${state.party} ${state.party===1?'person':'people'}</span><strong>~$${r.allowance*state.party}</strong></div><p class="trip-note">Excludes drinks, tax, tips, surcharges, and rides. Ride prices appear in Uber.</p><div class="trip-actions">${valid?`<a class="primary" href="${escape(l.booking)}" target="_blank" rel="noopener noreferrer">${r.walkIn?'View walk-in details':'Check restaurant & book'}</a><div class="ride-links"><a href="${escape(l.uber)}" target="_blank" rel="noopener noreferrer">Open Uber</a><a href="${escape(l.maps)}" target="_blank" rel="noopener noreferrer">View route</a></div>`:'<button class="primary" disabled>Update date & time to continue</button>'}</div><p class="trip-note">${r.note} Booking opens the official site; enter your date and guests there. Uber opens a request for now, not a scheduled ride. Nothing is purchased here.</p><div class="utility-actions"><button id="save-plan" ${!valid?'disabled':''}>♡ Save plan</button><button id="share-plan" ${!valid?'disabled':''}>⌘ Share</button><button id="calendar" ${!valid?'disabled':''}>▦ Calendar</button></div></div>`;
  for(const k of ['travel','buffer'])$('#'+k).onchange=e=>{if(!e.target.checkValidity())return e.target.reportValidity();state=normalize({...state,[k]:Number(e.target.value)});renderItinerary();};
  $('#save-plan').onclick=()=>{const data=readSaved();const hash=encodePlan(state,selected);if(data.some(x=>encodePlan(x.state,x.restaurant)===hash)){notify('This plan is already saved.');return;}if(writeSaved([{id:String(Date.now()),state:{...state},restaurant:selected},...data].slice(0,20)))notify('Saved on this device. Find it in Saved plans.');};
  $('#share-plan').onclick=()=>{const url=location.href.split('#')[0]+encodePlan(state,selected);modal('Good evenings are better shared.',`<p>This link contains your date, restaurant, starting point, and party size. Anyone with it can view the plan. It does not include a reservation or personal account details.</p><label for="share-url">Your plan link</label><input id="share-url" class="share-input" readonly value="${escape(url)}"><p><button id="copy-link" class="primary">Copy link</button></p>`);$('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(url);$('#copy-link').textContent='Copied!';}catch{$('#share-url').select();notify('Select and copy the link above.');}};};
  $('#calendar').onclick=()=>{const blob=new Blob([calendar(state,r)],{type:'text/calendar;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`sidequest-${state.date}.ics`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Calendar file downloaded. Your plan is marked unconfirmed.');};
}
$('#plan-form').onsubmit=e=>{e.preventDefault();if(!$('#plan-form').reportValidity())return;
  if($('#prompt').value.trim()!==lastPrompt){const result=parsePrompt($('#prompt').value,state);state=result.state;lastPrompt=$('#prompt').value;notice(result.recognized.length?`Picked up ${result.recognized.join(', ')}. Review the fields below; unrecognized requests (like quiet seating or allergies) are not applied.`:'No supported details found. Set your date, budget, guests, and starting point in the fields.',!result.recognized.length);}
  else notice('Your options are ready. Review the details, choose a place, then confirm with the restaurant.');
  selected=null;render();if(!validDinner())notice('Please choose a future dinner date and a time between 5–9pm. Restaurant hours and holiday closures must be checked separately.',true);else notify('Your evening options are ready.');
};
for(const key of ['date','time','party','budget','origin','cuisine'])$('#'+key).onchange=e=>{if(!e.target.checkValidity())return e.target.reportValidity();state=normalize({...state,[key]:e.target.value});notice('Updated from your fields. Editing a field takes priority until you change the prompt.');render();};
document.querySelectorAll('[data-vibe]').forEach(b=>b.onclick=()=>{state.vibe=b.dataset.vibe;render();});
const examples={date:'Date night for two on Friday at 7pm, under $85 each. Starting at the Ferry Building.',friends:'Dinner for four on Saturday at 6:30pm, budget $85 each, with friends. Starting at Union Square.',vegan:'Vegan sushi for two on Friday at 7pm, under $85 each. Starting at Salesforce Park.',casual:'Casual Greek dinner for two tomorrow at 6pm, budget $30 each. Starting at Hayes Valley.'};
document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{$('#prompt').value=examples[b.dataset.example];state=defaults();lastPrompt='';sync();$('#plan-form').requestSubmit();});
function reset(){state={...state,cuisine:'Any',vibe:'any',budget:150,party:2};selected=null;render();notice('Filters reset: any cuisine, any vibe, two guests, up to $150 per person.');}
$('#reset').onclick=reset;
function showSaved(){const data=readSaved();modal('Your saved evenings',data.length?`<p>Stored only in this browser. No account required.</p>${data.map(x=>{const r=restaurants.find(r=>r.id===x.restaurant);return `<article class="saved-item"><strong>${r.name}</strong><p>${escape(x.state.date)} · ${escape(x.state.time)} Pacific · ${x.state.party} guests</p><div><button class="outline" data-open="${escape(x.id)}">Open plan</button><button class="text-button" data-delete="${escape(x.id)}">Remove</button></div></article>`;}).join('')}`:'<div class="empty"><span class="empty-icon">♡</span><h3>A good evening belongs here.</h3><p>Choose a restaurant, then tap Save plan. Your plans stay on this device.</p></div>');
document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{const plan=data.find(x=>x.id===b.dataset.open);state=normalize(plan.state);selected=plan.restaurant;$('#prompt').value='';lastPrompt='';$('#modal').close();render();notice('Saved plan restored. Check the date and confirm availability before booking.');});
document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(writeSaved(data.filter(x=>x.id!==b.dataset.delete)))showSaved();});}
function about(){modal('Less planning. More going.',`<p>Sidequest connects a dinner idea to a practical evening plan. This free first release covers six curated San Francisco restaurants.</p><h3>1. Tell us the basics</h3><p>Try “Italian for two on Friday at 7pm, under $100.” A local, rule-based planner recognizes dates, times, guest counts, budgets, cuisines, and selected starting points. It is not an AI chat model. Review the fields; quiet seating, allergies, and other unsupported requests are not automatically handled.</p><h3>2. Connect your evening</h3><p>Pick a restaurant and adjust your travel allowance. The timeline includes an arrival buffer. The map is a schematic; Google Maps provides the real route and current traffic.</p><h3>3. Make it happen</h3><p>Open the restaurant’s official website to check hours, policies, and availability, and book there. Open Uber when you are ready to ride. Review pickup, destination, fare, and timing before confirming. Sidequest does not book, order, charge, or cancel on your behalf.</p><h3>What’s next</h3><p>Live availability, authorized booking and ride APIs, live routing, delivery ordering, and broader city coverage are not in this release.</p>`);}
$('#nav-about').onclick=about;$('#bottom-about').onclick=about;
$('#nav-saved').onclick=showSaved;$('#nav-plan').onclick=()=>$('#planner').scrollIntoView();
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}};
$('#privacy').onclick=()=>modal('Privacy & product details',`<p>Your prompt is processed in your browser. We do not run a backend, use analytics, collect payment details, or require an account. Saving a plan uses browser local storage; remove it from Saved plans to delete it.</p><p>Shared links contain the plan in the URL fragment. Anyone with that link can read it. Hosting providers receive ordinary web requests. Google Fonts receives font requests. Opening booking, Uber, or Maps links shares the relevant destination details with those services, under their own policies.</p><p>Restaurant details were reviewed on November 25, 2026 using official websites. Food allowances and vibe labels are editorial estimates, not quotes or verified availability. Menus, opening hours, holiday closures, booking rules, and fees can change. Confirm dietary needs directly with the venue.</p><p>Independent project; not affiliated with Uber, DoorDash, Google, or the restaurants. No paid services or API keys are used.</p><p><a href="https://github.com/Jameslovecs/sidequest" target="_blank" rel="noopener noreferrer">Source code, setup, and limitations on GitHub</a></p>`);
function loadHash(){const plan=decodePlan(location.hash);if(plan){state=plan.state;selected=plan.restaurant;$('#prompt').value='';lastPrompt='';notice('Shared plan loaded. This is not a reservation. Review the date and details before proceeding.');}else if(location.hash.startsWith('#plan='))notice('That shared link could not be read. Start a new plan below.',true);render();}
window.addEventListener('hashchange',loadHash);updateCount();loadHash();
